-- DB FIDDLE: paste this whole file in the LEFT panel (Schema SQL). Choose MySQL 8.0.
-- Contains: tables + raw data (30 + 3798 rows) + data cleaning. Then click Build.

CREATE TABLE employees (
    emp_id        VARCHAR(10) PRIMARY KEY,
    employee_name VARCHAR(60) NOT NULL,
    department    VARCHAR(30) NOT NULL
);

-- Raw table: everything VARCHAR on purpose, so nothing is lost while loading
CREATE TABLE raw_attendance (
    id               INT AUTO_INCREMENT PRIMARY KEY,
    emp_id           VARCHAR(20),
    employee_name    VARCHAR(80),
    department       VARCHAR(40),
    work_date        VARCHAR(20),
    work_mode        VARCHAR(30),
    status           VARCHAR(20),
    check_in         VARCHAR(15),
    check_out        VARCHAR(15),
    tasks_assigned   VARCHAR(5),
    tasks_completed  VARCHAR(5)
);


