-- 3a. Standardise text, parse dates and times, convert task counts
DROP TABLE IF EXISTS stg_attendance;
CREATE TABLE stg_attendance AS
SELECT
    id,
    UPPER(TRIM(emp_id)) AS emp_id,
    CASE
        WHEN TRIM(work_date) REGEXP '^[0-9]{4}-' THEN STR_TO_DATE(TRIM(work_date), '%Y-%m-%d')
        WHEN TRIM(work_date) LIKE '%/%'          THEN STR_TO_DATE(TRIM(work_date), '%d/%m/%Y')
        ELSE                                          STR_TO_DATE(TRIM(work_date), '%d-%m-%Y')
    END AS work_date,
    CASE LOWER(TRIM(work_mode))
        WHEN 'office'          THEN 'Office'
        WHEN 'wfo'             THEN 'Office'
        WHEN 'in office'       THEN 'Office'
        WHEN 'wfh'             THEN 'WFH'
        WHEN 'work from home'  THEN 'WFH'
        WHEN 'home'            THEN 'WFH'
    END AS work_mode,
    CASE LOWER(TRIM(status))
        WHEN 'present'  THEN 'Present'
        WHEN 'p'        THEN 'Present'
        WHEN 'absent'   THEN 'Absent'
        WHEN 'a'        THEN 'Absent'
        WHEN 'leave'    THEN 'Leave'
        WHEN 'on leave' THEN 'Leave'
        WHEN 'l'        THEN 'Leave'
        WHEN 'half day' THEN 'Half Day'
        WHEN 'half-day' THEN 'Half Day'
        WHEN 'hd'       THEN 'Half Day'
    END AS status,
    CASE
        WHEN NULLIF(TRIM(check_in), '') IS NULL        THEN NULL
        WHEN UPPER(TRIM(check_in)) LIKE '%M'           THEN STR_TO_DATE(TRIM(check_in), '%h:%i %p')
        ELSE                                                STR_TO_DATE(TRIM(check_in), '%H:%i')
    END AS check_in,
    CASE
        WHEN NULLIF(TRIM(check_out), '') IS NULL       THEN NULL
        WHEN UPPER(TRIM(check_out)) LIKE '%M'          THEN STR_TO_DATE(TRIM(check_out), '%h:%i %p')
        ELSE                                                STR_TO_DATE(TRIM(check_out), '%H:%i')
    END AS check_out,
    COALESCE(CAST(NULLIF(TRIM(tasks_assigned),  '') AS UNSIGNED), 0) AS tasks_assigned,
    COALESCE(CAST(NULLIF(TRIM(tasks_completed), '') AS UNSIGNED), 0) AS tasks_completed
FROM raw_attendance;


-- 3b. Remove duplicates, attach master data, impute missing times, cap tasks
DROP TABLE IF EXISTS attendance_clean;
CREATE TABLE attendance_clean AS
WITH dedup AS (
    SELECT s.*,
           ROW_NUMBER() OVER (PARTITION BY emp_id, work_date ORDER BY id) AS rn
    FROM stg_attendance s
),
d AS (
    SELECT * FROM dedup WHERE rn = 1
),
emp_avg AS (
    SELECT emp_id,
           SEC_TO_TIME(ROUND(AVG(TIME_TO_SEC(check_in))))  AS avg_in,
           SEC_TO_TIME(ROUND(AVG(TIME_TO_SEC(check_out)))) AS avg_out
    FROM d
    GROUP BY emp_id
)
SELECT
    d.emp_id,
    e.employee_name,
    e.department,
    d.work_date,
    d.work_mode,
    d.status,
    CASE WHEN d.status = 'Present' THEN COALESCE(d.check_in,  a.avg_in)  ELSE d.check_in  END AS check_in,
    CASE WHEN d.status = 'Present' THEN COALESCE(d.check_out, a.avg_out) ELSE d.check_out END AS check_out,
    d.tasks_assigned,
    LEAST(d.tasks_completed, d.tasks_assigned) AS tasks_completed,
    CASE
        WHEN d.status = 'Present' AND d.check_in  IS NULL THEN 'Check-in imputed'
        WHEN d.status = 'Present' AND d.check_out IS NULL THEN 'Check-out imputed'
        WHEN d.tasks_completed > d.tasks_assigned          THEN 'Tasks capped at assigned'
    END AS data_note
FROM d
JOIN employees e ON e.emp_id = d.emp_id
JOIN emp_avg  a ON a.emp_id = d.emp_id;

ALTER TABLE attendance_clean ADD PRIMARY KEY (emp_id, work_date);

-- 3c. Analysis view with derived columns (same definitions as the Excel file)
CREATE OR REPLACE VIEW vw_attendance AS
SELECT
    c.*,
    DATE_FORMAT(work_date, '%Y-%m')                                   AS ym,
    DATE_FORMAT(work_date, '%a')                                      AS weekday,
    ROUND(TIME_TO_SEC(TIMEDIFF(check_out, check_in)) / 3600, 2)       AS hours_worked,
    CASE WHEN status IN ('Present', 'Half Day') THEN 1 ELSE 0 END     AS attended,
    CASE WHEN status IN ('Present', 'Half Day') AND tasks_assigned > 0
         THEN tasks_completed / tasks_assigned END                    AS productivity,
    CASE WHEN check_in > '10:00:00' THEN 1 ELSE 0 END                 AS is_late
FROM attendance_clean c;

